root_nodes.mermaid:
stateDiagram-v2
    [*] --> ActiveDemand : 需求解构生成

    state "临时需求活跃中" as ActiveDemand {
        [*] --> Coding : 编码实现中
        Coding --> Verified : 验证通过
    }

    ActiveDemand --> LongTermRule : Agent 研判发现通用架构规范 (promote)
    ActiveDemand --> ArchivedDemand : Agent 研判当前需求已全部达成 (archive)

    state "晋升为项目长期规则" as LongTermRule {
        [*] --> SkeletonDB : 长期承重墙契约库
        SkeletonDB --> EffectiveAcrossTasks : 跨所有后续任务生效
    }

    state "安全归档不再激活" as ArchivedDemand {
        [*] --> ExitPrompt : 退出活跃 Prompt
        ExitPrompt --> CheckCompletion : 检查 Task 完成度
    }

    CheckCompletion --> TaskCompleted : 该 Task 所有需求均已归档
    TaskCompleted --> [*]
